import copy
import random
import unittest

from counting import BudgetExceeded, Counted, Ops, ShiftList, Tracked as T, CountingSeq as Seq, plain
from ledgerio.work import shift_groups




def oracle(a, b):
    return [a[i:i + b] for i in range(0, len(a), b)]


def wrap(a, b):
    return (ShiftList(a), b)

def small_args(rng):
    return ([rng.randrange(0, 50) for _ in range(rng.randrange(0, 25))], rng.randrange(1, 6))


class CorrectnessTests(unittest.TestCase):
    def test_matches_the_reference_on_random_inputs(self):
        rng = random.Random(1000)
        for _ in range(120):
            args = small_args(rng)
            self.assertEqual(shift_groups(*copy.deepcopy(args)), oracle(*copy.deepcopy(args)), args)

    def test_works_with_instrumented_values(self):
        rng = random.Random(1001)
        for _ in range(40):
            args = small_args(rng)
            self.assertEqual(plain(shift_groups(*wrap(*copy.deepcopy(args)))), oracle(*copy.deepcopy(args)), args)

    def test_empty_inputs(self):
        empty = ([], 3)
        self.assertEqual(shift_groups(*copy.deepcopy(empty)), oracle(*copy.deepcopy(empty)))

