import copy
import random
import unittest

from counting import BudgetExceeded, Counted, Ops, ShiftList, Tracked as T, CountingSeq as Seq, plain
from ledgerio.work import shift_groups




def oracle(a, b):
    return [a[i:i + b] for i in range(0, len(a), b)]


def wrap(a, b):
    return (ShiftList(a), b)

def big_args(rng, n):
    return ([rng.randrange(0, 1000) for _ in range(n)], 8)


class PerformanceTests(unittest.TestCase):
    def test_cost_grows_with_the_input(self):
        rng = random.Random(1000)
        n = 8000
        args = big_args(rng, n)
        wrapped = wrap(*copy.deepcopy(args))
        limit = 4 * n
        Ops.reset()
        Ops.budget = limit * 20
        try:
            got = shift_groups(*wrapped)
        except BudgetExceeded:
            self.fail("PERF: gave up after %d element moves for %d items (limit %d): elements are shifted or copied again and again (front pops, repeated slicing, membership + remove loops)" % (Ops.budget, n, limit))
        finally:
            Ops.budget = None
        ops = Ops.reads
        self.assertEqual(plain(got), oracle(*copy.deepcopy(args)))
        self.assertLessEqual(ops, limit, "PERF: %d element moves for %d items (limit %d): elements are shifted or copied again and again (front pops, repeated slicing, membership + remove loops)" % (ops, n, limit))

