def strip_blank_slots(slots, blank):
    """Calendar slots without blank entries."""
    return [item for item in slots if item != blank]


def describe(count, noun):
    """Pluralised count for log lines."""
    return "%d %s%s" % (count, noun, "" if count == 1 else "s")

